def finiteTensorInclusion (K : Complex ι) (p q : ℕ) :
    FiniteTensorChains K p q →ₗ[ℚ] FiniteBigradedTensorChains K :=
  DirectSum.lof ℚ (ℕ × ℕ) (fun ij => FiniteTensorChains K ij.1 ij.2) (p, q)

